column4:
.Entity > .label { font-family: sans-serif\s font-size: 12px\s }
.block > .shape { fill: #e8f0fa\s stroke: #4a7ea4\s }
.requirement > .shape { fill: #fff8c4\s stroke: #b39b2e\s }
.Relationship > .line { stroke: #333333\s stroke-width: 1px\s fill: none\s }
.flow > .line { stroke: #4a7ea4\s stroke-width: 2px\s }
.satisfies > .line { stroke-dasharray: 4 3\s }
.highlighted > .line { stroke: #d2691e\s stroke-width: 3px\s }
